146	  handle(event: ServerEvent) {
147	    switch (event.type) {
148	      case "session.input_transcript.delta": {
149	        // GPT-Live's transcript sometimes marks a break with "|" ("when is my| rent due").
150	        const delta = (event.delta ?? "").replace(/\|/g, " ");
