221	  /**
222	   * Words still unclaimed once the user has been quiet a while: a request GPT-Live never handed off becomes its own,
223	   * and small talk GPT-Live answered itself is dropped, so the next request doesn't start with it.
224	   */
225	  private claimUnheard() {
226	    if (this.now() - this.lastUserSpeech < UNCLAIMED_MS) return;
227	    const text = plain(this.heard.map(piece => piece.text).join(""));
228	    if (!looksLikeRequest(text)) { this.heard = []; return; }
229	    if (!this.lastDelegation) return;
230	    this.heard = [];
231	    this.deps.log?.(`claimed words GPT-Live never handed off: ${text.slice(0, 60)}`);
