236	  /** A typed message starts a task directly; its answer is spoken the same way. */
237	  typed(text: string) {
238	    const message = text.trim();
239	    if (!message) return;
240	    this.captionId++;
241	    this.captions = [...this.captions, { id: this.captionId, role: "user", text: message }];
242	    this.start(message, null);
243	  }
