245	  private caption(role: CallCaption["role"], words: string) {
246	    // Sound tags are not words, and can arrive in pieces between the other side's words.
247	    let delta = (this.openTag[role] + words).replace(/\[[^\]]*\]/g, "");
248	    // A "[" that never closes within a few words was just a bracket.
249	    const open = delta.length - delta.lastIndexOf("[") > 40 ? -1 : delta.lastIndexOf("[");
250	    this.openTag[role] = open < 0 ? "" : delta.slice(open);
251	    if (open >= 0) delta = delta.slice(0, open);
252	    if (!delta) return;
253	    const last = this.captions.at(-1);
254	    if (last?.role === role) this.captions = [...this.captions.slice(0, -1), { ...last, text: last.text + delta }];
255	    else this.captions = [...this.captions, { id: ++this.captionId, role, text: delta.trimStart() }];
256	    this.deps.onChange();
257	  }
