259	  private update(requestId: string, change: Partial<CallTask>) {
260	    this.tasks = this.tasks.map(task => task.requestId === requestId ? { ...task, ...change } : task);
261	    this.deps.onChange();
262	  }
263	
264	  /**
265	   * What Moneo needs to answer one request on its own: the requests still being answered separately, the call so far
266	   * to resolve "that" or "also", and what this call has already answered.
267	   */
268	  private brief() {
269	    return {
270	      via: "call", input: "voice",
271	      runningTasks: this.running.slice(-5).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300) })),
272	      recentTurns: this.captions.slice(-6).map(caption => ({ role: caption.role, text: caption.text.slice(-300) })),
273	      answered: this.tasks.flatMap(task => {
274	        const answer = this.answers.get(task.requestId);
275	        return answer ? [{ text: task.text.slice(0, 150), answer: answer.slice(0, 300) }] : [];
276	      }).slice(-4),
277	    };
278	  }
