280	  private start(text: string, delegationId: string | null) {
281	    const requestId = this.newId();
282	    const context = this.brief();
283	    this.tasks = [...this.tasks, { requestId, text, step: "starting", status: "running", delegationId, cards: [] }];
284	    this.deps.onChange();
285	    this.watchSlow(requestId);
286	    void this.run(requestId, text, context);
287	    return requestId;
288	  }
