290	  private async run(requestId: string, text: string, context: ReturnType<VoiceCallController["brief"]>) {
291	    const label = `"${text.slice(0, 120)}"`;
292	    // Read when needed: a late hand-off can take a request over while it runs.
293	    const via = () => this.tasks.find(item => item.requestId === requestId)?.delegationId ?? null;
294	    try {
295	      const result = await this.deps.ask({ conversationId: this.deps.conversationId, requestId, message: text.slice(0, 4000), context }, event => {
296	        if (event.type !== "tool" || event.state !== "running") return;
297	        if (event.name === "call_replace_task") this.replaced((event.input as { requestId?: unknown } | undefined)?.requestId);
298	        const step = stepFor(event.name);
299	        this.update(requestId, { step });
300	        if (via()) this.deps.send({ type: "session.thinking.append", delegation_id: via(), content: `Working on ${label}: ${step}.` });
301	      });
302	      const task = this.tasks.find(item => item.requestId === requestId);
303	      // Canceled from the list, or stopped because a correction replaced it: nothing to say.
304	      if (task?.status === "canceled") return;
305	      if (result.status === 409) { this.update(requestId, { status: "canceled", step: "stopped" }); return; }
306	      if (!result.ok || !result.body.answer) throw new Error(result.body.error ?? "No answer");
307	      const cards = answerCards(result.body.answer);
308	      this.answers.set(requestId, spokenAnswer(result.body.answer));
309	      this.update(requestId, { status: "done", step: "answered", cards });
310	      this.deps.onAnswer?.(text, result.body as ChatAnswer);
311	      // A typed request has no hand-off to answer through, so the result says outright that it is to be spoken.
312	      const delegationId = via();
313	      this.deliver(requestId, delegationId, [`Result for ${label}${delegationId ? "" : " (typed by the user in the call; say the result to them now, in the language of their quoted words)"}: ${spokenAnswer(result.body.answer)}`,
314	        cards.length ? `${cards.length} card${cards.length > 1 ? "s" : ""} on screen to tap; nothing is saved until then.` : ""].filter(Boolean).join(" "));
315	    } catch {
316	      if (this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
317	      this.update(requestId, { status: "failed", step: "failed" });
318	      this.deliver(requestId, via(), `Moneo couldn't get an answer for ${label}. Tell the user briefly and ask if they want you to try again.`);
319	    }
320	  }
