322	  /** One short spoken update for a task that runs long, once nobody is talking. Re-checks every second; ends when the task does. */
323	  private watchSlow(requestId: string, delay = SLOW_TASK_MS) {
324	    this.schedule(() => {
325	      const task = this.tasks.find(item => item.requestId === requestId);
326	      if (task?.status !== "running" || this.announced.has(requestId)) return;
327	      // Never in the middle of saying a result, or before one waiting to be said.
328	      if (this.speaking() || !this.resultSaid() || this.cut || this.outbox.length) return this.watchSlow(requestId, 1000);
329	      this.stillWorking([task]);
330	    }, delay);
331	  }
332	
333	  /**
334	   * Once Moneo has said a result and has no other to say next, it says what is still running, read right then, so it
335	   * never says it is waiting on a request that has finished. Re-checks every 300 ms; ends once a newer result goes out.
336	   */
337	  private followUp(handed: VoiceCallController["current"]) {
338	    this.schedule(() => {
339	      if (this.current !== handed || this.cut || this.outbox.length) return;
340	      if (this.speaking() || !this.resultSaid()) return this.followUp(handed);
341	      const waiting = this.running.filter(task => !this.announced.has(task.requestId));
342	      if (waiting.length) this.stillWorking(waiting);
343	    }, 300);
344	  }
345	
346	  private stillWorking(tasks: CallTask[]) {
347	    tasks.forEach(task => this.announced.add(task.requestId));
348	    const names = tasks.map(task => `"${task.text.slice(0, 120)}" (${task.step})`).join(", ");
349	    this.deps.send({ type: "session.commentary.append", delegation_id: tasks[0].delegationId,
350	      content: `Still working on ${names}. Say so in a few words${tasks.some(task => task.delegationId) ? "" : ", in the language of their quoted words"}.` });
351	  }
352	
353	  /** Results queue in the order they finish. */
354	  private deliver(requestId: string, delegationId: string | null, content: string) {
355	    this.outbox.push({ requestId, delegationId, content });
356	    this.flush();
357	  }
358	
359	  /**
360	   * A correction is replacing an earlier request: its result is not said, so Moneo never gives the old answer before
361	   * the corrected one. The server stops it or dismisses its cards.
362	   */
363	  private replaced(requestId: unknown) {
364	    const task = this.tasks.find(item => item.requestId === requestId);
365	    if (!task || task.status === "failed" || task.status === "canceled") return;
366	    this.outbox = this.outbox.filter(item => item.requestId !== task.requestId);
367	    // Nor is the rest of it said if the user cut it off.
368	    if (this.cut?.requestId === task.requestId) this.cut = null;
369	    this.update(task.requestId, { status: "canceled", step: "replaced" });
370	  }
371	
372	  /**
373	   * Hands over the next result once Moneo has said the previous one and nobody is talking. A result never says what
374	   * else is still running: by the time Moneo reaches the end of it, that may have finished too.
375	   */
376	  private flush() {
377	    if (this.flushing || !this.outbox.length || this.cut) return;
378	    if (this.speaking() || this.now() - this.lastUserSpeech < USER_PAUSE_MS || !this.resultSaid()) {
379	      this.flushing = true;
380	      this.schedule(() => { this.flushing = false; this.flush(); }, 300);
381	      return;
382	    }
383	    const { requestId, delegationId, content } = this.outbox.shift()!;
384	    this.current = { requestId, delegationId, content, at: this.now() };
385	    this.deps.log?.(`handed over: ${content.slice(0, 60)}`);
386	    this.deps.send({ type: "session.commentary.append", delegation_id: delegationId, content: `${content} ${ONLY_THIS_RESULT}` });
387	    this.followUp(this.current);
388	    this.flush();
389	  }
390	
391	  /**
392	   * Once the user has finished and Moneo has answered them (or had a few seconds to), Moneo is asked to finish the
393	   * result it was cut off in before any other. A short "mm-hm" over it is not an interruption.
394	   */
395	  private resume() {
396	    this.schedule(() => {
397	      const cut = this.cut;
398	      if (!cut) return;
399	      if (this.speaking() || this.now() - this.lastUserSpeech < USER_PAUSE_MS
400	        || (this.lastMoneo <= this.lastUserSpeech && this.now() - this.lastUserSpeech < RESUME_AFTER_MS)) return this.resume();
401	      this.cut = null;
402	      const words = cut.words.trim().split(/\s+/).length;
403	      this.deps.log?.(words >= 3 ? "resuming the cut-off result" : "not resuming: only a backchannel");
404	      if (words >= 3) this.outbox.unshift({ requestId: cut.requestId, delegationId: cut.delegationId,
405	        content: `The user talked over you while you were giving this result. If you hadn't finished it, finish the part you hadn't said yet, without repeating what you already said; if you had, or they asked you to stop or skip it, say nothing more about it. ${cut.content}` });
406	      this.flush();
407	    }, 300);
408	  }
409	
410	  /** Marks a task canceled; the caller asks the server to stop it. */
411	  cancel(requestId: string) { this.update(requestId, { status: "canceled", step: "stopped" }); }
412	}
